99	/**
100	 * When --providers is used alongside a config file that has providers defined,
101	 * maps each CLI provider token to a matching config provider (preserving its config
102	 * options like num_ctx, temperature). Unmatched tokens are kept as bare strings.
103	 *
104	 * Matching priority per token:
105	 * 1. Exact match on provider id
106	 * 2. Exact match on provider label
107	 * 3. Provider-prefix match: config id ends with `:cliProvider` (e.g. CLI `llama3.1:8b`
108	 *    matches config `ollama:llama3.1:8b`). First match wins if multiple configs share a suffix.
109	 * 4. No match: keep raw CLI string for fresh provider creation
110	 */
111	export function resolveCliProvidersWithConfig(
112	  cliProviders: string[],
113	  configProviders: UnifiedConfig['providers'],
114	): UnifiedConfig['providers'] {
115	  if (!configProviders || !Array.isArray(configProviders)) {
116	    return cliProviders;
117	  }
118	
119	  // Pre-compute id/label for each config provider once, rather than
120	  // re-calling getProviderIdAndLabel on every find() iteration.
121	  const indexed = configProviders.map((cp, i) => ({
122	    provider: cp,
123	    ...getProviderIdAndLabel(cp, i),
124	  }));
125	
126	  return cliProviders.map((cliProvider) => {
127	    // Separate passes enforce documented priority so an exact id match
128	    // is always preferred over a suffix match earlier in the array.
129	    const exactId = indexed.find((entry) => entry.id === cliProvider);
130	    if (exactId) {
131	      return exactId.provider;
132	    }
133	
134	    const exactLabel = indexed.find((entry) => entry.label === cliProvider);
135	    if (exactLabel) {
136	      return exactLabel.provider;
137	    }
138	
139	    const prefixMatch = indexed.find((entry) => entry.id.endsWith(':' + cliProvider));
140	    if (prefixMatch) {
141	      return prefixMatch.provider;
142	    }
143	
144	    return cliProvider;
145	  });
146	}
